import React, { useState, useEffect } from 'react';

const Explore = ({ onSelectStock }) => {
    const [indices, setIndices] = useState({});
    const [recentlyViewed, setRecentlyViewed] = useState([]);
    const [popularStocks, setPopularStocks] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        fetchIndices();
        fetchPopularStocks();
        // Load recently viewed from localStorage
        const saved = localStorage.getItem('recentlyViewed');
        if (saved) {
            setRecentlyViewed(JSON.parse(saved));
        }
    }, []);

    const fetchIndices = async () => {
        try {
            const response = await fetch('http://localhost:5000/api/index-data');
            const data = await response.json();
            setIndices(data);
        } catch (error) {
            console.error('Error fetching indices:', error);
        }
        setLoading(false);
    };

    const fetchPopularStocks = async () => {
        // Popular stocks list
        const popular = [
            'RELIANCE', 'TCS', 'HDFCBANK', 'INFY', 'ICICIBANK',
            'SBIN', 'BHARTIARTL', 'ITC', 'WIPRO', 'HCLTECH'
        ];
        try {
            const response = await fetch('http://localhost:5000/api/prices', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ symbols: popular })
            });
            const data = await response.json();
            const stocksWithData = popular.map(symbol => ({
                symbol,
                price: data[symbol] || null,
                change: null // Would need historical data for change
            }));
            setPopularStocks(stocksWithData);
        } catch (error) {
            console.error('Error fetching popular stocks:', error);
        }
    };

    const addToRecentlyViewed = (symbol) => {
        const updated = [symbol, ...recentlyViewed.filter(s => s !== symbol)].slice(0, 10);
        setRecentlyViewed(updated);
        localStorage.setItem('recentlyViewed', JSON.stringify(updated));
    };

    const handleStockClick = (symbol) => {
        addToRecentlyViewed(symbol);
        onSelectStock(symbol);
    };

    return (
        <div style={{ padding: '20px 0' }}>
            {/* Market Indices */}
            <div style={{
                display: 'flex',
                gap: '30px',
                padding: '15px 20px',
                background: '#141b2b',
                borderRadius: '10px',
                border: '1px solid #2a3a5c',
                marginBottom: '20px',
                flexWrap: 'wrap'
            }}>
                {Object.entries(indices).map(([name, data]) => (
                    <div key={name} style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                        <span style={{ fontWeight: 'bold', color: '#8a9bb5', fontSize: '14px' }}>
                            {name}
                        </span>
                        <span style={{ fontSize: '18px', fontWeight: 'bold', color: '#e0e6ed' }}>
                            {data.value ? data.value.toFixed(2) : 'N/A'}
                        </span>
                        <span style={{
                            color: data.change && data.change >= 0 ? '#4CAF50' : '#dc3545',
                            fontSize: '14px',
                            fontWeight: 'bold'
                        }}>
                            {data.change && data.change >= 0 ? '+' : ''}{data.change ? data.change.toFixed(2) : '0'}
                            ({data.change_percent ? data.change_percent.toFixed(2) : '0'}%)
                        </span>
                    </div>
                ))}
            </div>

            {/* Recently Viewed */}
            {recentlyViewed.length > 0 && (
                <div style={{ marginBottom: '20px' }}>
                    <div style={{ 
                        display: 'flex', 
                        justifyContent: 'space-between',
                        alignItems: 'center',
                        marginBottom: '10px'
                    }}>
                        <h3 style={{ color: '#e0e6ed', fontSize: '16px' }}>Recently viewed</h3>
                    </div>
                    <div style={{ display: 'flex', gap: '10px', flexWrap: 'wrap' }}>
                        {recentlyViewed.map((symbol) => (
                            <div
                                key={symbol}
                                onClick={() => handleStockClick(symbol)}
                                style={{
                                    padding: '8px 16px',
                                    background: '#1a2332',
                                    borderRadius: '20px',
                                    border: '1px solid #2a3a5c',
                                    cursor: 'pointer',
                                    color: '#e0e6ed',
                                    fontSize: '14px',
                                    transition: 'all 0.2s'
                                }}
                                onMouseEnter={(e) => e.target.style.background = '#2a3a5c'}
                                onMouseLeave={(e) => e.target.style.background = '#1a2332'}
                            >
                                {symbol}
                            </div>
                        ))}
                    </div>
                </div>
            )}

            {/* Popular/Most Traded Stocks */}
            <div>
                <h3 style={{ color: '#e0e6ed', fontSize: '16px', marginBottom: '10px' }}>
                    Most traded on Groww
                </h3>
                <div style={{
                    display: 'grid',
                    gridTemplateColumns: 'repeat(auto-fill, minmax(200px, 1fr))',
                    gap: '10px'
                }}>
                    {popularStocks.map((stock) => (
                        <div
                            key={stock.symbol}
                            onClick={() => handleStockClick(stock.symbol)}
                            style={{
                                padding: '12px 16px',
                                background: '#141b2b',
                                borderRadius: '8px',
                                border: '1px solid #2a3a5c',
                                cursor: 'pointer',
                                transition: 'all 0.2s',
                                display: 'flex',
                                justifyContent: 'space-between',
                                alignItems: 'center'
                            }}
                            onMouseEnter={(e) => e.target.style.background = '#1a2332'}
                            onMouseLeave={(e) => e.target.style.background = '#141b2b'}
                        >
                            <div>
                                <div style={{ color: '#e0e6ed', fontWeight: 'bold', fontSize: '14px' }}>
                                    {stock.symbol}
                                </div>
                                <div style={{ color: '#8a9bb5', fontSize: '12px' }}>
                                    {stock.price ? `₹${stock.price.toFixed(2)}` : 'N/A'}
                                </div>
                            </div>
                            {stock.price && (
                                <span style={{
                                    color: stock.change && stock.change >= 0 ? '#4CAF50' : '#8a9bb5',
                                    fontSize: '12px'
                                }}>
                                    {stock.change ? (stock.change >= 0 ? '+' : '') + stock.change.toFixed(2) : '0'}%
                                </span>
                            )}
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
};

export default Explore;
